import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    x = int(next(iterator))
    y = int(next(iterator))

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    # Check each day from 0 to n-1 (representing days 1 to n)
    for i in range(n):
        is_not_so_rainy = True

        # Check x days before
        start_before = max(0, i - x)
        for j in range(start_before, i):
            if a[j] <= a[i]:
                is_not_so_rainy = False
                break
        if not is_not_so_rainy:
            continue

        # Check y days after
        end_after = min(n - 1, i + y)
        for j in range(i + 1, end_after + 1):
            if a[j] <= a[i]:
                is_not_so_rainy = False
                break
        if not is_not_so_rainy:
            continue

        # Found the earliest day
        print(i + 1)
        return

